interface IGovernedAccessControl is IAccessControl, IERC165 {}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

interface IRedemptionManager {
    enum RedemptionStatus {
        NONE,
        PENDING,
        CLAIMABLE,
        CLAIMED,
        CANCELLED
    }

    struct RedeemRequestState {
        uint256 pendingShares;
        uint256 pendingAssets;
        uint256 claimableShares;
        uint256 claimableAssets;
    }

    struct RedemptionState {
        uint256 requestId;
        address controller;
        address owner;
        uint256 shares;
        uint256 assetsReserved;
        uint256 requestedAt;
        uint256 eligibleAt;
        bytes32 policyId;
        RedemptionStatus status;
    }

    struct RedemptionPolicy {
        uint256 cooldown;
        uint256 maxRequestShares;
        bool enabled;
    }

    struct RedemptionControls {
        uint256 cooldown;
        uint256 maxServiceBatchShares;
        bool requestPaused;
        bool claimPaused;
        bool servicePaused;
        bool cancelPaused;
        address serviceAuthority;
        uint256 updatedAt;
    }

    struct RedemptionServiceResult {
        uint256 serviceId;
        uint256 requestsServiced;
        uint256 sharesMadeClaimable;
        uint256 assetsReserved;
    }

    event RedemptionsServiced(
        uint256 indexed serviceId, uint256 requestsServiced, uint256 sharesMadeClaimable, uint256 assetsReserved
    );
    event RedemptionControlsUpdated(
        uint256 cooldown,
        uint256 maxServiceBatchShares,
        bool requestPaused,
        bool claimPaused,
        bool servicePaused,
        bool cancelPaused,
        address serviceAuthority
    );
    event RedemptionPauseUpdated(bytes32 indexed pause, bool paused);
    event RedemptionPolicyUpdated(bytes32 indexed policyId, uint256 cooldown, uint256 maxRequestShares, bool enabled);
    event AccountRedemptionPolicyUpdated(address indexed account, bytes32 indexed policyId);
    event RedeemRequestCancelled(
        uint256 indexed requestId,
        address indexed controller,
        address indexed owner,
        uint256 sharesReturned,
        uint256 assetsReleased
    );

    function getRedeemRequest(address controller) external view returns (RedeemRequestState memory);

    function redemptionState(uint256 requestId, address controller) external view returns (RedemptionState memory);

    function redemptionControls() external view returns (RedemptionControls memory);

    function redemptionPolicy(bytes32 policyId) external view returns (RedemptionPolicy memory);

    function accountRedemptionPolicy(address account) external view returns (bytes32);

    function serviceRedemptions(uint256 maxShares) external returns (RedemptionServiceResult memory);

    function serviceRedeemRequest(uint256 requestId, address controller)
        external
        returns (RedemptionServiceResult memory);

    function cancelRedeemRequest(uint256 requestId, address controller) external returns (uint256 sharesReturned);

    function setRedemptionPolicy(bytes32 policyId, RedemptionPolicy calldata policy) external;

    function setAccountRedemptionPolicy(address account, bytes32 policyId) external;
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {IGovernedAccessControl} from "./IGovernedAccessControl.sol";
import {IAsyncRedeemVault} from "./IAsyncRedeemVault.sol";
import {IRedemptionManager} from "./IRedemptionManager.sol";
import {IRewardManager} from "./IRewardManager.sol";
import {IVaultShareToken} from "./IVaultShareToken.sol";

interface IStakedUSDx is
    IVaultShareToken,
    IAsyncRedeemVault,
    IRewardManager,
    IRedemptionManager,
    IGovernedAccessControl
{
    struct AccountState {
        uint256 shareBalance;
        uint256 assetsValue;
        uint256 pendingRedeemAssets;
        uint256 claimableRedeemAssets;
        bytes32 restrictionStatus;
        bytes32 blockedActions;
        bytes32 restrictionBasis;
    }

    event CooldownDurationUpdated(uint256 previousDuration, uint256 newDuration);
    event DepositPauseUpdated(bool paused);
    event RestrictionUpdated(address indexed account, bytes32 indexed status, bytes32 reasonCode, bytes32 authorityRef);
    event LockedAmountRedistributed(address indexed from, address indexed to, uint256 shares);
    event RedeemRequestRedistributed(
        uint256 indexed requestId,
        address indexed fromController,
        address indexed toController,
        uint256 shares,
        uint256 assets,
        uint8 status
    );
    event Rescue(address indexed token, address indexed to, uint256 amount);

    error InvalidAmount();
    error InvalidToken();
    error MinSharesViolation();
    error OperationNotAllowed();
    error StillVesting();
    error InvalidCooldown();
    error InvalidZeroAddress();
    error InsufficientClaimable();
    error Insolvent();

    function REWARD_MANAGER_ROLE() external view returns (bytes32);

    function PAUSER_ROLE() external view returns (bytes32);

    function RESTRICTION_ROLE() external view returns (bytes32);

    function REDEMPTION_SERVICER_ROLE() external view returns (bytes32);

    function DEFAULT_REDEMPTION_POLICY_ID() external view returns (bytes32);

    function MAX_COOLDOWN_DURATION() external view returns (uint256);

    function REQUEST_ID() external view returns (uint256);

    function addToBlacklist(address target, bool isFullRestriction) external;

    function removeFromBlacklist(address target, bool isFullRestriction) external;

    function redistributeLockedAmount(address from, address to) external;

    function redistributeRedeemRequest(uint256 requestId, address controller, address to)
        external
        returns (uint256 shares, uint256 assets);

    function rescueTokens(address token, uint256 amount, address to) external;

    function setCooldownDuration(uint256 duration) external;

    function depositPaused() external view returns (bool);

    function setDepositPause(bool paused) external;

    function pauseDeposits() external;

    function getAccountState(address account) external view returns (AccountState memory);

    function share() external view returns (address shareTokenAddress);
}

