pragma solidity 0.8.30;

import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";

interface IVaultShareToken is IERC4626 {
    struct VaultState {
        uint256 totalSupply;
        uint256 totalAssets;
        uint256 accountedAssets;
        uint256 pendingRedeemAssets;
        uint256 claimableRedeemAssets;
        uint256 redeemLiabilities;
        uint256 requiredAssets;
        uint256 assetBalance;
        uint256 exchangeRate;
        uint256 cooldown;
        bool solvent;
    }

    function accountedAssets() external view returns (uint256);

    function pendingRedeemAssets() external view returns (uint256);

    function claimableRedeemAssets() external view returns (uint256);

    function cooldownDuration() external view returns (uint256);

    function getVaultState() external view returns (VaultState memory);

    function exchangeRate() external view returns (uint256);
}
